function runWorkspaceChecks(){
 const results=[];
 function check(name,fn){const node=document.createElement('div');document.body.append(node);try{fn(node);results.push({name,pass:true})}catch(e){results.push({name,pass:false,error:String(e)})}finally{node.remove()}}
 const assert=(ok,message)=>{if(!ok)throw Error(message)};
 const fixture={workspace:{files:{'a.txt':'alpha','b.txt':'beta'},start:'a.txt',goal:{current:'b.txt'}}};
 check('Unsaved changes block buffer switches; write permits switch',node=>{const r=Workspace.create(node,fixture);r.cm.setValue('changed');let blocked=false;try{r.command('buffer','b.txt')}catch{blocked=true}assert(blocked&&r.current()==='a.txt','unsaved switch was not blocked');r.command('write');r.command('buffer','b.txt');assert(r.current()==='b.txt'&&r.snapshot().saved['a.txt']==='changed','write lost data')});
 check('Split views share a buffer; closing a view retains the file',node=>{const r=Workspace.create(node,fixture);r.command('vsplit');r.cm.setValue('both views');assert(r.snapshot().files[r.state().panes[1]]==='both views','split did not share text');r.command('write');r.command('close');assert(r.state().panes.length===1&&r.state().listed.length===2,'closing removed a buffer')});
 check('Only refuses to hide unsaved work in another pane',node=>{const r=Workspace.create(node,fixture);r.command('vsplit','b.txt');r.cm.setValue('unsaved');r.command('wincmd','l');let blocked=false;try{r.command('only')}catch{blocked=true}assert(blocked&&r.state().panes.length===2,'only hid unsaved work')});
 check('Deleting buffer preserves its file and it can be reopened',node=>{const r=Workspace.create(node,fixture);r.command('bdelete');assert(!r.state().listed.includes('a.txt')&&r.snapshot().files['a.txt']==='alpha','buffer deletion erased file');r.command('edit','a.txt');assert(r.current()==='a.txt','file could not reopen')});
 check('Recursive search scope and flags; workspace resume',node=>{const m=missions.find(q=>q.workspace&&q.title.startsWith('Find launch()'));const r=Workspace.create(node,m);r.command('vimgrep','/launch/j src/**/*.js');assert(r.current()==='notes.txt'&&r.state().quickfix.length===2,'glob or j flag incorrect');r.command('copen');r.command('cnext');const save=r.snapshot();const next=document.createElement('div');node.append(next);const restored=Workspace.create(next,m,save);assert(restored.current()===r.current()&&restored.state().qopen&&restored.state().quickfix.length===2,'resume lost workspace');assert(restored.cm.getCursor().line===1,'resume lost cursor')});
 check('Search failure does not destroy existing result list',node=>{const m={workspace:{files:{'a.js':'TODO tea','b.js':'TODO toast'},start:'a.js',goal:{current:'b.js'}}};const r=Workspace.create(node,m);r.command('vimgrep','/TODO/ *.js');const before=JSON.stringify(r.state().quickfix);let failed=false;try{r.command('vimgrep','/absent/ *.js')}catch{failed=true}assert(failed&&JSON.stringify(r.state().quickfix)===before,'search failure mutated results')});
 return results;
}
